import{_ as t,o as a,c as s,ah as o}from"./chunks/framework.ChH6X6u6.js";const u=JSON.parse('{"title":"School structure","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/admin/structure-etablissement.md","filePath":"src/en/guide/admin/structure-etablissement.md"}'),r={name:"en/guide/admin/structure-etablissement.md"};function n(i,e,l,d,c,h){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="school-structure" tabindex="-1">School structure <a class="header-anchor" href="#school-structure" aria-label="Permalink to &quot;School structure&quot;">​</a></h1><p>This section groups all of ERA&#39;s base configuration: this is what you set up at the start of the year, before staff and students can start working in the app. The usual order is: academic year → sites → departments → levels → classes → subjects → subjects by department → evaluation types → academic periods → competencies (if needed).</p><h2 id="academic-years" tabindex="-1">Academic years <a class="header-anchor" href="#academic-years" aria-label="Permalink to &quot;Academic years&quot;">​</a></h2><p><strong>School setup → Academic Years</strong> lists your school&#39;s academic years, with the number of classes in each. Only one year is &quot;Current&quot; at a time — it&#39;s the one that appears by default on the dashboard and on new forms.</p><p>To create an academic year:</p><ol><li>Click <strong>New academic year</strong>.</li><li>Fill in the fields below.</li><li>Click <strong>Save</strong>.</li></ol><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td>Label</td><td>e.g. &quot;2025-2026&quot;</td></tr><tr><td>Start date</td><td>—</td></tr><tr><td>End date</td><td>—</td></tr></tbody></table><p>From the list, the <strong>Set as current</strong> button switches the current year. Deleting an academic year is permanent and irreversible.</p><h3 id="closing-a-year-or-a-term" tabindex="-1">Closing a year or a term <a class="header-anchor" href="#closing-a-year-or-a-term" aria-label="Permalink to &quot;Closing a year or a term&quot;">​</a></h3><p>Once a year or a term is over, close it to prevent inadvertent entries: a teacher reopening an old link will no longer change the grades of a term already handed to families.</p><p>The <strong>Status</strong> column of <strong>Academic Years</strong> and <strong>Academic Terms</strong> carries the actions:</p><ul><li><strong>Close</strong> — available once the end date has passed. Grades, attendance, bulletins, lesson logs, competency observations and incidents of the period become read-only, for everyone. The screens concerned show a message and their <strong>Save</strong> button is disabled.</li><li><strong>Reopen</strong> — for a one-off correction. You give a reason and a duration (48 hours by default, a week at most): the period closes again on its own when the time is up, so nobody has to remember. The reason and the author are recorded in the <a href="/era-guide/en/guide/admin/demo-et-journal.html">activity log</a>.</li><li><strong>Cancel closure</strong> — if it was closed by mistake. The period becomes editable again with no time limit.</li></ul><p>Closing a year closes everything it contains, including the days between two terms (holidays, catch-up sessions). A reopened term stays editable even if its year is closed.</p><div class="tip custom-block"><p class="custom-block-title">The cash desk is never frozen</p><p>Closing only covers teaching records. Payments, discounts and expenses stay possible on a closed year: a school almost always collects arrears after lessons are over.</p></div><h3 id="preparing-the-next-year" tabindex="-1">Preparing the next year <a class="header-anchor" href="#preparing-the-next-year" aria-label="Permalink to &quot;Preparing the next year&quot;">​</a></h3><p>Before the new school year, there is no need to recreate every class and fee structure by hand: carry them over from an earlier year.</p><ol><li>Create the new academic year (e.g. &quot;2027-2028&quot;) without setting it as current.</li><li>On its row, click <strong>Prepare</strong>.</li><li>In <strong>Copy from</strong>, choose the year to copy: the previous year is selected by default.</li><li>Check the preview of classes and fee structures, and tick what you want to copy.</li><li>Click <strong>Copy into 2027-2028</strong>.</li></ol><p>Copied: each class&#39;s name, site, department, level, series, capacity and bulletin template, and fee structures with all their fees. You then adjust the amounts or classes that change.</p><p><strong>Not</strong> copied: students, homeroom teachers, teacher assignments and timetables, which change from one year to the next.</p><p>Anything the new year already has is left as it is and marked <strong>Already there</strong>: a class with the same name on the same site, a fee structure for the same site and department. You can therefore run the copy again without creating duplicates. The current year does not change: you switch it with <strong>Set as current</strong> when the time comes. A closed year cannot be prepared.</p><h2 id="sites" tabindex="-1">Sites <a class="header-anchor" href="#sites" aria-label="Permalink to &quot;Sites&quot;">​</a></h2><p>If your school has multiple campuses, <strong>School setup → Sites</strong> lets you manage them. A site only has two fields: <strong>Name</strong> and <strong>Address</strong>. Every department, class, fee structure, and employee is then attached to a site — if you only have one campus, create a single site and attach everything else to it.</p><p>To create a site: go to <strong>School setup → Sites</strong>, click <strong>New site</strong>, fill in the name (and the optional address), then <strong>Save</strong>.</p><h3 id="site-logo" tabindex="-1">Site logo <a class="header-anchor" href="#site-logo" aria-label="Permalink to &quot;Site logo&quot;">​</a></h3><p>Once the site exists, its <strong>Edit</strong> page offers a <strong>site logo</strong>, below the name/address form. That logo is printed, in place of the school logo, on:</p><ul><li>the <strong>bulletins</strong> of the classes attached to this site;</li><li>the <strong>payment receipts</strong> of students enrolled in one of this site&#39;s classes.</li></ul><p>Sites with no logo of their own keep using the one from the <a href="/era-guide/en/guide/admin/parametres-application.html">application settings</a> — so there&#39;s nothing to do if all your campuses share one identity.</p><p>Only the logo changes: the menu and the public home page keep the school logo, and the address, phone and email printed on receipts are still the ones from the application settings.</p><p>Accepted formats: PNG, JPG, WebP or SVG, 2 MB maximum. The <strong>Remove</strong> button deletes the site&#39;s logo and brings back the school one. Already-generated bulletins and receipts aren&#39;t rewritten: the change applies to documents produced afterwards.</p><h2 id="departments" tabindex="-1">Departments <a class="header-anchor" href="#departments" aria-label="Permalink to &quot;Departments&quot;">​</a></h2><p>A department corresponds to a level or track (e.g. &quot;Preschool&quot;, &quot;Middle School&quot;, &quot;IB Senior Year&quot;). <strong>School setup → Departments</strong> lists the school&#39;s departments along with the sites where each is active.</p><p>To create a department:</p><ol><li>Click <strong>New department</strong>.</li><li>Fill in the fields below.</li><li>Click <strong>Save</strong>.</li></ol><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td>Name</td><td>—</td></tr><tr><td>Type</td><td>Nursery, Preschool, Elementary, Middle school, High school, IB, or University</td></tr><tr><td>Curriculum</td><td>French or Togolese — determines the grading rules applied to this department</td></tr><tr><td>Available at</td><td>check one or more sites where this department is active</td></tr></tbody></table><h2 id="levels" tabindex="-1">Levels <a class="header-anchor" href="#levels" aria-label="Permalink to &quot;Levels&quot;">​</a></h2><p>A level is what a class teaches, whatever the year: &quot;Grade 6&quot;, &quot;Year 12&quot;. Several parallel classes share one level. Levels prepare moving students up: they say where students who pass go next.</p><p><strong>School setup → Levels</strong> shows levels department by department, in order. The <strong>↑</strong> and <strong>↓</strong> arrows change that order. Each level shows its next level and how many classes use it.</p><p>To create a level:</p><ol><li>Click <strong>New level</strong>.</li><li>Fill in the fields below.</li><li>Click <strong>Save</strong>. The level is added at the end of its department.</li></ol><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td>Department</td><td>—</td></tr><tr><td>Name</td><td>unique within the department</td></tr><tr><td>Next level</td><td>where students who pass go; it can be in another department</td></tr><tr><td>Last level of the school</td><td>students who pass leave the school after this level, so it has no next level</td></tr><tr><td>Exam year</td><td>moving up depends on a national exam: no decision will be proposed automatically</td></tr></tbody></table><p>A level with no next level that isn&#39;t the last one shows <strong>Next level not set</strong>: remember to fill it in. A level used by classes can be neither deleted nor moved to another department.</p><div class="tip custom-block"><p class="custom-block-title">Create levels in any order</p><p>The next level is picked from existing levels: start with the highest one so you can link each level to the next as you go, then order them with the arrows.</p></div><h2 id="classes" tabindex="-1">Classes <a class="header-anchor" href="#classes" aria-label="Permalink to &quot;Classes&quot;">​</a></h2><p><strong>School setup → Classes</strong> lists classes, with filters by site, department, and academic year, and each class&#39;s enrolled headcount (out of its capacity, if you set one).</p><p>To create a class:</p><ol><li>Click <strong>New class</strong>.</li><li>Fill in the &quot;Structure&quot; section fields below.</li><li>Optionally, fill in the &quot;Options&quot; section fields below.</li><li>Click <strong>Save</strong>.</li></ol><p>&quot;Structure&quot; section:</p><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td>Name</td><td>—</td></tr><tr><td>Site</td><td>—</td></tr><tr><td>Department</td><td>—</td></tr><tr><td>Level</td><td>optional; one of the department&#39;s levels, see <a href="#levels">Levels</a></td></tr><tr><td>Series</td><td>optional; e.g. &quot;C&quot;, &quot;D&quot;, &quot;A4&quot;, to tell classes of the same level apart</td></tr><tr><td>Academic year</td><td>—</td></tr></tbody></table><p>&quot;Options&quot; section (all optional):</p><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td>Capacity</td><td>seat limit; leave blank for &quot;No limit&quot;</td></tr><tr><td>Homeroom teacher</td><td>chosen from existing teachers</td></tr><tr><td>Bulletin template</td><td>Classic, Compact, or Traditional (French-style); leave blank to use the &quot;Instance default&quot;</td></tr></tbody></table><p>From the class list, each row also offers quick links to that class&#39;s <strong>Timetable</strong> and <strong>Report cards</strong> — no need to go back through the menu.</p><h2 id="subjects" tabindex="-1">Subjects <a class="header-anchor" href="#subjects" aria-label="Permalink to &quot;Subjects&quot;">​</a></h2><p><strong>School setup → Subjects</strong> is the school&#39;s global subject catalog (e.g. &quot;Mathematics&quot;, &quot;English&quot;). A subject only has a name; attaching it to a department (see below) is what defines its coefficient and its grading scale.</p><p>To create a subject: <strong>School setup → Subjects</strong>, <strong>New subject</strong>, fill in the name, <strong>Save</strong>.</p><h2 id="subjects-by-department" tabindex="-1">Subjects by department <a class="header-anchor" href="#subjects-by-department" aria-label="Permalink to &quot;Subjects by department&quot;">​</a></h2><p><strong>School setup → Subjects by Department</strong> attaches a catalog subject to a department, with the grading rules specific to that department.</p><p>To create an assignment:</p><ol><li>Click <strong>New assignment</strong>.</li><li>Fill in the fields below.</li><li>Click <strong>Save</strong>.</li></ol><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td>Department</td><td>—</td></tr><tr><td>Subject</td><td>—</td></tr><tr><td>Coefficient</td><td>—</td></tr><tr><td>Grading scale</td><td>maximum possible score; 20 by default</td></tr><tr><td>Specialty subject (chosen by student)</td><td>check if this subject isn&#39;t taken by every student in the department but chosen individually (see <a href="/era-guide/en/guide/admin/eleves-tuteurs.html">Students and guardians</a>); leave unchecked for a core subject, applied automatically to everyone</td></tr></tbody></table><h2 id="evaluation-types" tabindex="-1">Evaluation types <a class="header-anchor" href="#evaluation-types" aria-label="Permalink to &quot;Evaluation types&quot;">​</a></h2><p><strong>School setup → Evaluation Types</strong> defines the evaluation categories used by teachers (homework, exam, quiz...) and the weight of each in a subject&#39;s average calculation.</p><p>To create a type: <strong>School setup → Evaluation Types</strong>, <strong>New evaluation type</strong>, fill in the <strong>Name</strong> and the <strong>Weight</strong> (e.g. 1 for homework, 2 for an exam), <strong>Save</strong>.</p><h2 id="academic-periods" tabindex="-1">Academic periods <a class="header-anchor" href="#academic-periods" aria-label="Permalink to &quot;Academic periods&quot;">​</a></h2><p><strong>School setup → Academic Periods</strong> defines the grading periods (terms, semesters...) of an academic year — they&#39;re used both for grade entry by teachers and for publishing report cards.</p><p>To create a period:</p><ol><li>Click <strong>New period</strong>.</li><li>Fill in the fields below.</li><li>Click <strong>Save</strong>.</li></ol><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td>Academic year</td><td>—</td></tr><tr><td>Name</td><td>e.g. &quot;Term 1&quot;</td></tr><tr><td>Start date</td><td>—</td></tr><tr><td>End date</td><td>—</td></tr><tr><td>Order</td><td>this period&#39;s position among the others in the same year</td></tr></tbody></table><h2 id="competencies" tabindex="-1">Competencies <a class="header-anchor" href="#competencies" aria-label="Permalink to &quot;Competencies&quot;">​</a></h2><p><strong>School setup → Competencies</strong> only applies to qualitative departments (nursery, preschool): instead of numeric grades, teachers observe competencies there (e.g. &quot;Recognizes colors&quot;).</p><p>To create a competency: <strong>School setup → Competencies</strong>, <strong>New competency</strong>, choose the qualitative <strong>Department</strong> concerned, fill in the <strong>Name</strong>, <strong>Save</strong>.</p>',70)])])}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
